  task automatic run_hmao_engine(
    input  int          timeout_cy,
    output logic        ok,
    output logic        decision,
    output logic [7:0]  fault_bits
  );
    logic done;
    ok = 1'b0; decision = 1'b0; fault_bits = 8'h0;
    @(posedge hmao_clk); hmao_start <= 1'b1;
    @(posedge hmao_clk); hmao_start <= 1'b0;
    done = 1'b0;
    for (int c = 0; c < timeout_cy; c++) begin
      @(posedge hmao_clk);
      if (hmao_complete) begin done = 1'b1; break; end
    end
    @(posedge hmao_clk);
    if (done) begin
      ok = 1'b1; decision = hmao_decision; fault_bits = fault_out;
    end
  endtask

  // expected_label: 2=GRANT, 1=VETO, 0=BOUNDARY (log only, no assertion)
  task automatic run_collision_tc(
    input string tc_name, input string traj_hex, input string wm_hex,
    input string category, input real clearance_m, input int expected_label
  );
    logic hmao_ok, decision;
    logic [7:0] fault_bits;
    string traj_path, wm_path;

    traj_path = {`HEX_DIR, "/", traj_hex};
    wm_path   = {`HEX_DIR, "/", wm_hex};

    if (hmao_complete) clear_irq();

    $readmemh(traj_path, traj_mem);
    foreach (wm_mem[i]) wm_mem[i] = 32'h0;
    $readmemh(wm_path, wm_mem);
    @(posedge hmao_clk);

    run_hmao_engine(2_000_000, hmao_ok, decision, fault_bits);
    check({tc_name, "_complete"}, hmao_ok);

    if (hmao_ok) begin
      case (expected_label)
        2: begin
          $display("[%s] %s clearance=%0.2fm expect=GRANT got=%s faults=0x%02h",
                    tc_name, category, clearance_m, decision?"GRANT":"VETO", fault_bits);
          check({tc_name, "_expect_grant"}, decision == 1'b1);
        end
        1: begin
          $display("[%s] %s clearance=%0.2fm expect=VETO got=%s faults=0x%02h",
                    tc_name, category, clearance_m, decision?"GRANT":"VETO", fault_bits);
          check({tc_name, "_expect_veto"}, decision == 1'b0);
        end
        default: begin
          $display("[%s] %s clearance=%0.2fm BOUNDARY (no assert) got=%s faults=0x%02h viol=%016h lat=%0d mg=%04h/%04h/%04h",
                    tc_name, category, clearance_m, decision?"GRANT":"VETO", fault_bits, hmao_violation, hmao_latency, lat_margin, long_margin, time_margin);
          if (decision) boundary_grant_cnt++; else boundary_veto_cnt++;
        end
      endcase
      // Regardless of label: watchdog must never spuriously fire on real data.
      check({tc_name, "_no_wdt_fault"}, (fault_bits & 8'h40) == 8'h00);
    end
    clear_irq();
  endtask

